function tierClass(tier) {
  const lvl = { 'Bronze': 5, 'Silver': 4, 'Gold': 3, 'Platinum': 2, 'Diamond': 1 };
  if (tier in lvl) {
    return 'icon-tier-' + lvl[tier];
  } else {
    return '';
  }
}

function gaEvent(category, action, label) {
  ga('send', 'event', {
    eventCategory: category,
    eventAction: action,
    eventLabel: label
  });
}

